  auth.uid() = user_id
  AND (SELECT is_verified FROM public.profiles WHERE id = auth.uid()) = true
);
REVOKE INSERT, UPDATE, DELETE ON public.border_permits FROM anon, authenticated;

NOTIFY pgrst, 'reload schema';

COMMIT;

